{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.daily_fifo_ageing AS WITH inv_current_by_sku AS ( SELECT date AS snapshot_date, sku_group, SUM( COALESCE(qty_available,0) + COALESCE(qty_offline_available,0) + COALESCE(qty_jit,0) ) AS inv_current FROM snitch_db.maplemonk.cogs_daily_snapshot WHERE date >= \'2026-04-15\' AND date < \'2027-01-01\' GROUP BY 1,2 ), inward_lots AS ( SELECT UPPER( IFF( UPPER(REPLACE(p.\"Item Type skuCode\",\' \',\'\')) LIKE \'MP%\' OR UPPER(REPLACE(p.\"Item Type skuCode\",\' \',\'\')) LIKE \'4C-%\', REGEXP_REPLACE( REPLACE(p.\"Item Type skuCode\",\' \',\'\'), \'^([^-]+-[^-]+-[^-]+).*$\', \'\\1\' ), REGEXP_REPLACE( REPLACE(p.\"Item Type skuCode\",\' \',\'\'), \'^([^-]+-[^-]+).*$\', \'\\1\' ) ) ) AS sku_group, p.\"PUTAWAY_UPDATED\"::DATE AS inward_date, SUM(p.\"PUTAWAY_COMPLETED_QUANTITY\") AS inward_qty FROM snitch_db.maplemonk.putaway_tracking p WHERE LOWER(final_type) = \'new inward\' GROUP BY 1,2 ), fifo_base AS ( SELECT ic.snapshot_date, ic.sku_group, ic.inv_current, il.inward_date, il.inward_qty, DATEDIFF( \'day\', il.inward_date, ic.snapshot_date ) AS lot_age_days FROM inv_current_by_sku ic JOIN inward_lots il ON ic.sku_group = il.sku_group AND il.inward_date <= ic.snapshot_date ), fifo_running AS ( SELECT *, SUM(inward_qty) OVER ( PARTITION BY snapshot_date, sku_group ORDER BY inward_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_inward_qty, SUM(inward_qty) OVER ( PARTITION BY snapshot_date, sku_group ORDER BY inward_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) - inward_qty AS cum_inward_qty_prev FROM fifo_base ), fifo_totals AS ( SELECT snapshot_date, sku_group, MAX(cum_inward_qty) AS total_inward_qty, MAX(inv_current) AS inv_current FROM fifo_running GROUP BY 1,2 ), fifo_remaining AS ( SELECT f.snapshot_date, f.sku_group, f.inward_date, f.inward_qty, f.lot_age_days, t.inv_current, t.total_inward_qty, GREATEST( t.total_inward_qty - t.inv_current, 0 ) AS consumed_qty, GREATEST( LEAST( f.inward_qty, GREATEST( t.total_inward_qty - t.inv_current, 0 ) - f.cum_inward_qty_prev ), 0 ) AS consumed_in_lot, GREATEST( f.inward_qty - GREATEST( LEAST( f.inward_qty, GREATEST( t.total_inward_qty - t.inv_current, 0 ) - f.cum_inward_qty_prev ), 0 ), 0 ) AS remaining_qty FROM fifo_running f LEFT JOIN fifo_totals t ON f.snapshot_date = t.snapshot_date AND f.sku_group = t.sku_group ), weighted_age AS ( SELECT snapshot_date AS date, sku_group, MAX(inv_current) AS inv_current, SUM(remaining_qty) AS remaining_qty, CASE WHEN SUM(remaining_qty) = 0 THEN 0 ELSE SUM( remaining_qty * lot_age_days ) / NULLIF( SUM(remaining_qty), 0 ) END AS weighted_age_days FROM fifo_remaining GROUP BY 1,2 ), ageing_bucket AS ( SELECT date, sku_group, inv_current, weighted_age_days, CASE WHEN weighted_age_days <= 30 THEN \'0-30\' WHEN weighted_age_days <= 60 THEN \'30-60\' WHEN weighted_age_days <= 90 THEN \'60-90\' WHEN weighted_age_days <= 120 THEN \'90-120\' WHEN weighted_age_days <= 180 THEN \'120-180\' WHEN weighted_age_days <= 270 THEN \'180-270\' WHEN weighted_age_days <= 360 THEN \'270-360\' ELSE \'360+\' END AS ageing_bucket FROM weighted_age ) SELECT a.date, a.sku_group, a.inv_current, ROUND(a.weighted_age_days,2) AS weighted_age_days, a.ageing_bucket FROM ageing_bucket a ORDER BY 1,2;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            